function cosine(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i];
  }
  return dot / (Math.sqrt(na) * Math.sqrt(nb));
}
function topK(query, docs, k) {
  return docs
    .map(d => ({ id: d.id, score: cosine(query, d.vector) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, k)
    .map(d => d.id);
}
```
`O(n·d + n log n)`. At 50M docs, use an ANN index (HNSW) in a vector database.
